    // Assign the second inputs of the gates as specified
    // XOR: second input is the flip-flop's own output
    // AND: second input is the complemented output
    // OR:  second input is the complemented output
    wire xor_in  = q0 ^ x;       // XOR with x
    wire and_in  = x & ~q1;      // AND with complemented q1
    wire or_in   = x | ~q2;      // OR with complemented q2

