module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);

    // State encoding: 0=INIT, 1=GOT_1, 2=GOT_11, 3=GOT_110
    typedef enum logic [1:0] {
        INIT   = 2'b00,
        GOT_1  = 2'b01,
        GOT_11 = 2'b10,
        GOT_110= 2'b11
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset)
    always_ff @(posedge clk) begin
        if (reset)
            state <= INIT;
        else
            state <= next_state;
    end

    // Next-state logic (Moore machine)
    always_comb begin
        case (state)
            INIT:     if (data == 1'b1)
                        next_state = GOT_1;
                      else
                        next_state = INIT;

            GOT_1:    if (data == 1'b1)
                        next_state = GOT_11;
                      else
                        next_state = INIT;

            GOT_11:   if (data == 1'b0)
                        next_state = GOT_110;
                      else
                        next_state = GOT_1;   // another '1' keeps us looking for the second '1'

            GOT_110:  if (data == 1'b1)
                        next_state = INIT;   // sequence 1101 detected
                      else
                        next_state = INIT;   // wrong bit, start over

            default:  next_state = INIT;
        endcase
    end

    // Output logic (Moore: output depends only on state)
    // start_shifting stays high forever once the sequence is found,
    // and holds until reset.
    assign start_shifting = (state == GOT_110) ? 1'b1 : 1'b0;

endmodule

