module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // State register: 2 bits to encode the previous water level state
    // 00: Below s[0] (lowest)
    // 01: Between s[1] and s[0]
    // 10: Between s[2] and s[1]
    // 11: Above s[2] (highest)
    reg [1:0] state, next_state;

    // Combinational logic for next state and output assignment
    always @(*) begin
        // Default assignments (hold previous values)
        next_state = state;
        fr0 = 1'b0;
        fr1 = 1'b0;
        fr2 = 1'b0;
        dfr = 1'b0;

        // Synchronous reset: equivalent to "low for a long time"
        if (reset) begin
            next_state = 2'b00; // Below s[0]
            fr0 = 1'b1;
            fr1 = 1'b1;
            fr2 = 1'b1;
            dfr = 1'b1;
        end else begin
            // Determine current sensor condition
            // s[2] highest, s[1] middle, s[0] lowest
            // We assume active-high sensors based on the specification tables.
            wire s2 = s[2];
            wire s1 = s[1];
            wire s0 = s[0];

            // ---------- Above s[2] (s[2] asserted) ----------
            if (s2) begin
                // fr0, fr1, fr2 are all 0 (None)
                // dfr = 0 (Supplemental flow valve closed)
                // State goes to 11 (Above s[2])
                next_state = 2'b11;
                // Outputs remain 0 (default from above)
            end
            // ---------- Between s[2] and s[1] (s[1] asserted, s[2] not) ----------
            else if (s1) begin
                // Nominal Flow Rate Inputs to be Asserted: fr0
                fr0 = 1'b1;
                // dfr depends on previous state:
                // If previous level was lower than current (state < 2'b01 i.e. 00),
                // open Supplemental flow valve (dfr = 1).
                // Otherwise (state was already between s[2] and s[1] or above),
                // dfr = 0.
                if (state < 2'b01) begin
                    dfr = 1'b1;
                end else begin
                    dfr = 1'b0;
                end
                // State goes to 10 (Between s[2] and s[1])
                next_state = 2'b10;
            end
            // ---------- Between s[1] and s[0] (s[0] asserted, s[1] not) ----------
            else if (s0) begin
                // Nominal Flow Rate Inputs to be Asserted: fr0, fr1
                fr0 = 1'b1;
                fr1 = 1'b1;
                // dfr depends on previous state:
                // If previous level was lower than current (state < 2'b01 i.e. 00),
                // open Supplemental flow valve (dfr = 1).
                // Otherwise (state was between s[1] and s[0] or above),
                // dfr = 0.
                if (state < 2'b01) begin
                    dfr = 1'b1;
                end else begin
                    dfr = 1'b0;
                end
                // State goes to 01 (Between s[1] and s[0])
                next_state = 2'b01;
            end
            // ---------- Below s[0] (no sensors asserted) ----------
            else begin
                // Nominal Flow Rate Inputs to be Asserted: fr0, fr1, fr2
                fr0 = 1'b1;
                fr1 = 1'b1;
                fr2 = 1'b1;
                // dfr = 1 (Supplemental flow valve opened) as per "maximum flow"
                dfr = 1'b1;
                // State goes to 00 (Below s[0])
                next_state = 2'b00;
            end
        end
    end

    // State register (flip-flops)
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            state <= next_state;
        end
    end

endmodule

