module TopModule (
    input  logic clk,
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);

// FSM state encoding (2 bits)
typedef enum logic [1:0] {
    S_A    = 2'b00,  // Beginning state (reset held)
    S_B    = 2'b01,  // Output f = 1 for one cycle
    S_C    = 2'b10,  // Monitoring x for pattern 1,0,1
    S_D    = 2'b11   // g = 1, waiting for y within 2 cycles
} state_t;

state_t state, next_state;

// Registers for x and y history
// x_shift holds the last 3 x values (oldest at [2], newest at [0])
logic [2:0] x_shift;
// y_shift holds the last 2 y values (newest at [0])
logic [1:0] y_shift;

// State register (positive-edge triggered, synchronous active-low reset)
always_ff @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        state <= S_A;
        x_shift <= 3'b000;
        y_shift <= 2'b00;
        f <= 1'b0;
        g <= 1'b0;
    end else begin
        state <= next_state;

        // Shift x register (newest at [0])
        x_shift <= {x_shift[1:0], x};
        // Shift y register (newest at [0])
        y_shift <= {y_shift[0], y};

        // Default: keep outputs stable
        f <= 1'b0;
        g <= 1'b0;

        case (state)
            S_A: begin
                // While reset is asserted, stay in S_A.
                // When resetn is de-asserted, go to S_B after the next clock edge.
                if (resetn) begin
                    next_state = S_B;
                end else begin
                    next_state = S_A;
                end
            end

            S_B: begin
                // f is set to 1 for this cycle only.
                f <= 1'b1;
                // After one cycle in S_B, move to S_C to start monitoring x.
                next_state = S_C;
            end

            S_C: begin
                // Default: stay in S_C
                next_state = S_C;

                // Detect pattern: (x_shift[2] == 1) && (x_shift[1] == 0) && (x_shift[0] == 1)
                // x_shift[2] is x from 2 cycles ago,
                // x_shift[1] is x from 1 cycle ago,
                // x_shift[0] is the current x (sampled at posedge).
                if ((x_shift[2] == 1'b1) && (x_shift[1] == 1'b0) && (x_shift[0] == 1'b1)) begin
                    next_state = S_D;
                end
            end

            S_D: begin
                // g = 1 is maintained as long as y becomes 1 within two cycles.
                g <= 1'b1;

                // Check y history: y_shift[0] is the most recent y,
                // y_shift[1] is the previous y.
                // If either is 1, keep g=1 (stay in S_D).
                // If neither is 1 within two cycles, set g=0 permanently.
                if (y_shift[0] == 1'b1 || y_shift[1] == 1'b1) begin
                    // y became 1 within the window; maintain g=1.
                    next_state = S_D;
                end else begin
                    // y did not become 1 within two cycles; set g=0 permanently.
                    // Transition to a state where g stays 0.
                    // We repurpose S_A as the permanent-0 state since we have
                    // a limited 2-bit encoding, or simply stay in S_D with g=0.
                    // The spec requires g=0 permanently until reset.
                    next_state = S_A; 
                end
            end
        endcase
    end
end
